const items = $input.all(); // Ambil data input 

for (let item of items) {
  const binaryData = item.binary?.Upload_CV__PDF_;

  if (binaryData) {
    item.json.cv_base64 = binaryData.data; // Data base64 internal 
    item.json.fileName = binaryData.fileName;
  }

  // Tambahkan tanggal format Indonesia menggunakan Luxon 
  item.json.tanggal_input = DateTime.now().toFormat('dd-MM-yyyy HH:mm');
}

return items;

const items = $input.all();

for (let item of items) {

  const aiResponseText = item.json.text;

  try {

    // Bersihkan markdown
    const cleanJson = aiResponseText
      .replace(/```json|```/g, '')
      .trim();

    // Parse JSON
    const parsedData = JSON.parse(cleanJson);

    // Simpan hasil
    item.json.ai_name = parsedData.candidate_name;

    // EMAIL
    item.json.ai_email = parsedData.email || "Email tidak ditemukan";

    item.json.ai_exp = parsedData.years_of_experience;

    item.json.ai_skills = parsedData.top_skills.join(", ");

    item.json.ai_summary = parsedData.summary;

    item.json.ai_score = parsedData.score;

    item.json.ai_rec = parsedData.hiring_recommendation;

  } catch (error) {

    item.json.error = "Gagal parsing JSON";

    item.json.raw_output = aiResponseText;

  }

}

return items;
